const root='/home/ubuntu/dev/explorakit';
const req=require('node:module').createRequire(root+'/package.json');
const assert=req('node:assert/strict'),fs=req('node:fs'),http=req('node:http'),{once}=req('node:events'),{randomUUID}=req('node:crypto');
if(!/test/i.test(process.env.DB_TEST_NAME||''))throw Error('Dedicated test database required');
