 for(const[key,name]of Object.entries(names))assert.equal(await page.locator(`[data-badge-key="${key}"] h4`).innerText(),name);
 assert.equal(await page.locator('[data-badge-key="lake_badge"]').getAttribute('data-badge-earned'),'true');await pictures('renamed-badges');
 const [after]=await db.execute('SELECT badge_key,awarded_at FROM player_badges WHERE user_id=?',[userId]);assert.deepEqual(after,before);assert.deepEqual(errors,[]);passed=true;const result={names,earnedBadgeAndTimestampPreserved:true,otherBadgesUnchanged:true,viewports:4,screens,errors};fs.writeFileSync(out+'/results.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{if(!passed&&page)await page.screenshot({path:out+'/failure.png'}).catch(()=>{});await browser?.close();await new Promise(r=>io.close(r));await new Promise(r=>setTimeout(r,200));if(userId)await db.execute('DELETE FROM users WHERE id=?',[userId]);await db.end();}})().catch(e=>{console.error(e.stack);process.exitCode=1});
